// The repo's own lint: one rule per entry, each a regex over every file in src/.
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const RULES = [
  { pattern: /\bvar\s/, message: 'use let or const instead of var' },
];

let failed = 0;
for (const name of readdirSync('src')) {
  const lines = readFileSync(join('src', name), 'utf8').split('\n');
  lines.forEach((line, i) => {
    for (const rule of RULES) if (rule.pattern.test(line)) { console.error(`src/${name}:${i + 1} ${rule.message}`); failed++; }
  });
}
process.exit(failed ? 1 : 0);
